const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),reverseCache=new WeakMap();
export const SAMPLER_INSTRUMENT={name:'EXO SLICE',subtitle:'SAMPLER / PADS',pack:'exo',color:'#d2aa78',description:'Importe ton audio, découpe ses attaques et joue tes slices ou un sample accordé dans le piano roll.',controls:[
 {key:'transpose',name:'Accordage',min:-24,max:24,step:1,default:0,unit:'st'},
 {key:'attack',name:'Attaque',min:.001,max:.2,step:.001,default:.003,unit:'s'},
 {key:'release',name:'Release',min:.005,max:1,step:.005,default:.06,unit:'s'},
 {key:'output',name:'Sortie',min:-24,max:6,step:.5,default:-6,unit:'dB'}]};
export function sliceSettings(raw={},duration=0){const end=Math.max(0,duration),marks=[0,...(Array.isArray(raw.markers)?raw.markers:[]).filter(Number.isFinite).map(x=>clamp(x,0,end)),end].sort((a,b)=>a-b).filter((v,i,a)=>!i||v-a[i-1]>.01);if(end&&marks.at(-1)!==end)marks.push(end);return {assetId:typeof raw.assetId==='string'?raw.assetId:'',mode:raw.mode==='chromatic'?'chromatic':'slices',root:clamp(Math.round(Number.isFinite(raw.root)?raw.root:60),0,127),reverse:raw.reverse===true,markers:marks.length>33?[...marks.slice(0,32),end]:marks};}
export function evenSlices(duration,count=16){return Array.from({length:clamp(Math.round(count),1,32)+1},(_,i)=>duration*i/count);}
export function detectSlices(buffer,maxSlices=16){
 const data=buffer.getChannelData(0),hop=256,energies=[];let max=0;for(let i=0;i<data.length;i+=hop){let sum=0;for(let j=i;j<Math.min(i+hop,data.length);j++)sum+=data[j]*data[j];const value=Math.sqrt(sum/hop);max=Math.max(max,value);energies.push(value);}
 const candidates=[];for(let i=1;i<energies.length-1;i++){const before=energies.slice(Math.max(0,i-5),i).reduce((a,b)=>a+b,0)/Math.min(i,5),strength=energies[i]-before;if(energies[i]>max*.06&&strength>max*.06&&energies[i]>=energies[i+1])candidates.push({time:i*hop/buffer.sampleRate,strength});}
 const selected=[0];for(const c of candidates.sort((a,b)=>b.strength-a.strength)){if(c.time<buffer.duration-.03&&selected.every(t=>Math.abs(t-c.time)>.08)){selected.push(c.time);if(selected.length>=maxSlices)break;}}
 return [...selected.sort((a,b)=>a-b),buffer.duration];
}
export function samplerVoice(ctx,out,buffer,midi,time,duration,raw={},params={},velocity=1,remember){
 if(!buffer||velocity<=0)return;const s=sliceSettings(raw,buffer.duration),index=Math.round(midi-s.root);let start=0,end=buffer.duration,rate=2**(((s.mode==='chromatic'?midi-s.root:0)+(params.transpose||0))/12);
 if(s.mode==='slices'){if(index<0||index>=s.markers.length-1)return;start=s.markers[index];end=s.markers[index+1];}
 let sample=buffer;if(s.reverse){sample=reverseCache.get(buffer);if(!sample){sample=ctx.createBuffer(buffer.numberOfChannels,buffer.length,buffer.sampleRate);for(let c=0;c<buffer.numberOfChannels;c++){const data=sample.getChannelData(c),source=buffer.getChannelData(c);for(let i=0;i<data.length;i++)data[i]=source[data.length-i-1];}reverseCache.set(buffer,sample);}start=buffer.duration-end;}
 const t=Math.max(ctx.currentTime,time),available=(end-(s.mode==='slices'?s.markers[index]:0))/rate,held=s.mode==='slices'?available:Math.min(available,Math.max(.01,duration)+(params.release??.06)),attack=Math.min(params.attack??.003,held/3),release=Math.min(params.release??.06,held/3),source=ctx.createBufferSource(),env=ctx.createGain();source.buffer=sample;source.playbackRate.value=rate;source.connect(env);env.connect(out);const gain=10**((params.output??-6)/20)*clamp(velocity,0,1);env.gain.setValueAtTime(0,t);env.gain.linearRampToValueAtTime(gain,t+attack);env.gain.setValueAtTime(gain,t+held-release);env.gain.linearRampToValueAtTime(0,t+held);source.start(t,start,held*rate);remember?.(source);source.addEventListener('ended',()=>{source.disconnect();env.disconnect();});return source;
}
export function mountSampler({panel,track,engine,assets,checkpoint,changed,save,toast,esc,insertPattern}){
 const box=document.createElement('section');box.className='slice-player';panel.querySelector('.plugin-window-params').before(box);
 const asset=()=>assets.get(track.sampler?.assetId);
 function render(){const a=asset(),s=track.sampler=sliceSettings(track.sampler,a?.buffer.duration||0);box.innerHTML=`<div class="slice-heading"><div><span>WARLIKE / EXO</span><h2>SLICE</h2><p>Ton audio devient un instrument.</p></div><label class="outline-btn">Charger un sample<input type="file" accept="audio/*" id="sliceFile" hidden></label></div><strong>${esc(a?.name||'Aucun sample chargé')}</strong><div class="workflow-row"><label>Jeu<select id="sliceMode"><option value="slices">Slices · un son par note</option><option value="chromatic" ${s.mode==='chromatic'?'selected':''}>Chromatique · sample accordé</option></select></label><label>Note racine MIDI<input id="sliceRoot" type="number" min="0" max="127" value="${s.root}"></label><label><input id="sliceReverse" type="checkbox" ${s.reverse?'checked':''}> Reverse</label></div>${a?`<svg id="sliceWave" viewBox="0 0 600 100" preserveAspectRatio="none" aria-label="Forme d’onde : cliquer pour ajouter une coupe"><polyline points="${waveform(a.buffer)}"/>${s.markers.slice(1,-1).map(t=>`<path d="M${t/a.buffer.duration*600} 0V100"/>`).join('')}</svg><small>Clique sur l’onde pour ajouter une coupe. ${a.buffer.duration.toFixed(2)} s · ${s.markers.length-1} slices.</small><div class="workflow-row"><button id="sliceDetect" class="outline-btn">Détecter les attaques</button><select id="sliceCount" aria-label="Nombre de slices"><option>4</option><option>8</option><option selected>16</option></select><button id="sliceEven" class="outline-btn">Découper régulièrement</button><button id="sliceClear" class="outline-btn">Effacer les coupes</button></div><div class="slice-pads">${s.markers.slice(0,-1).map((t,i)=>`<button data-slice-pad="${i}" aria-label="Jouer la slice ${i+1}"><b>${String(i+1).padStart(2,'0')}</b><small>MIDI ${s.root+i} · ${t.toFixed(2)} s</small></button>`).join('')}</div><div class="workflow-row"><button id="slicePattern" class="primary-btn">Créer un pattern de slices</button><button id="sliceStop" class="outline-btn">Arrêter les pads</button></div>`:'<p class="slice-empty">Charge une boucle, une voix ou une percussion. Jusqu’à 120 secondes par sample. Le fichier est conservé avec ton projet.</p>'}`;
  box.querySelector('#sliceFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Choisis un sample de moins de 20 Mo.');await engine.init();const data=await file.arrayBuffer(),buffer=await engine.ctx.decodeAudioData(data.slice(0));if(buffer.duration>120)throw Error('Découpe un extrait de moins de 120 secondes.');checkpoint();const assetId=Math.random().toString(36).slice(2,11);assets.set(assetId,{name:file.name,data,buffer});track.sampler={assetId,mode:'slices',root:60,markers:detectSlices(buffer)};changed();render();toast('Sample chargé dans EXO Slice.');}catch(error){toast(error.message);}};
  box.querySelector('#sliceMode').onchange=e=>{checkpoint();s.mode=e.target.value;changed();render();};box.querySelector('#sliceRoot').onchange=e=>{checkpoint();s.root=clamp(Number(e.target.value)||0,0,127);changed();render();};box.querySelector('#sliceReverse').onchange=e=>{checkpoint();s.reverse=e.target.checked;changed();};
  if(!a)return;const update=markers=>{checkpoint();track.sampler={...s,markers};changed();render();};box.querySelector('#sliceDetect').onclick=()=>update(detectSlices(a.buffer));box.querySelector('#sliceEven').onclick=()=>update(evenSlices(a.buffer.duration,Number(box.querySelector('#sliceCount').value)));box.querySelector('#sliceClear').onclick=()=>update([0,a.buffer.duration]);box.querySelector('#sliceWave').onpointerdown=e=>{const r=e.currentTarget.getBoundingClientRect();if(s.markers.length>=33){toast('Maximum : 32 slices.');return;}update([...s.markers,(e.clientX-r.left)/r.width*a.buffer.duration]);};for(const pad of box.querySelectorAll('[data-slice-pad]'))pad.onclick=()=>engine.preview('sampler',s.root+Number(pad.dataset.slicePad),track.id);box.querySelector('#slicePattern').onclick=()=>insertPattern(track,s);box.querySelector('#sliceStop').onclick=()=>engine.killVoices();
 }
 render();
}
function waveform(buffer){const data=buffer.getChannelData(0),points=[];for(let i=0;i<300;i++){let peak=0;const start=Math.floor(i/300*data.length),end=Math.floor((i+1)/300*data.length);for(let j=start;j<end;j+=Math.max(1,Math.floor((end-start)/24)))peak=Math.max(peak,Math.abs(data[j]));points.push(`${i*2},${50-peak*44}`,`${i*2},${50+peak*44}`);}return points.join(' ');}
